-- =============================================================================
-- PagLaafi — Données initiales
--
-- ⚠️ Données de DÉMONSTRATION NON VÉRIFIÉES (statuts, tarifs, contacts,
-- traductions), reprises de l'application. Elles sont insérées avec
-- verifie = false : elles restent MASQUÉES en mode réel tant que le superadmin
-- ne les a pas vérifiées auprès des structures (replit.md : ne jamais inventer
-- de centres, contacts ou tarifs).
--
-- Exécution : pnpm run db:migrer -- --seed (relançable : rien n'est inséré en double).
-- =============================================================================

insert into public.centres (
  nom, nom_court, lieu, ville, adresse, telephone, lat, lng, statut, statut_libelle, appareil,
  appareil_fonctionnel, agents_presents, description_personnel, file_attente, attente_estimee,
  examens, visites_confirmees_jour,
  message_audio_fr, message_audio_en, message_audio_moore, message_audio_dioula,
  verifie
)
select * from (values
  ('CMA de Schiphra (Centre Médical avec Antenne Chirurgicale)', 'CMA Schiphra', 'Tanghin, Secteur 17, Ouagadougou', 'Ouagadougou', 'Tanghin, Arrondissement 4 (ex-Secteur 30), Ouagadougou', '+226 25 36 30 70', 12.405, -1.518, 'available'::public.statut_centre, 'Disponible · Attente fluide', 'Mammographe numérique Hologic opérationnel', true, 4, '2 sages-femmes, 1 radiologue, 1 technicienne radio', 8, '~15 à 20 min',
   '[{"name":"Palpation clinique mammaire","price":0,"free":true,"notes":"Dépistage gratuit tous les matins"},{"name":"Échographie mammaire bilatérale","price":6000,"free":false},{"name":"Mammographie numérique","price":12000,"free":false,"notes":"Résultats en 48h"}]'::jsonb, 48,
   'Bonjour, ici la sage-femme de Schiphra. Notre mammographe fonctionne parfaitement aujourd''hui. L''attente est faible, moins de 20 minutes.',
   'Hello, this is the midwife from Schiphra. Our digital mammography unit is fully functional today with minimal wait time (under 20 minutes).',
   'Ne y beogo pagbã fãa, CMA Schiphra tɩɩm zĩiga yaa kaset. Masã masã, mammographie masĩnã tʋmdame tɩ zĩigã pa noom ye. Wa-y laafi.',
   'Aw ni sɔgɔma, CMA Schiphra kɛnɛyaso la masin bɛ baara kɛ kosɛbɛ bi. Mɔgɔ caman t''a la, aw bɛ se ka na sisan.',
   false),
  ('Centre Hospitalier Universitaire de Bogodogo (CHU-B)', 'CHU Bogodogo', 'Secteur 24, Ouagadougou', 'Ouagadougou', 'Boulevard des Tansoba, Arrondissement 5, Ouagadougou', '+226 25 37 40 40', 12.338, -1.488, 'busy'::public.statut_centre, 'Forte affluence · Prévoir attente', 'Mammographe opérationnel (2 appareils sur 2)', true, 6, '3 radiologues en poste, 3 sages-femmes', 46, '~1h15 à 1h30',
   '[{"name":"Examen clinique & sensibilisation","price":0,"free":true,"notes":"Prise en charge Octobre Rose"},{"name":"Échographie mammaire haute résolution","price":7500,"free":false},{"name":"Mammographie de dépistage","price":10000,"free":false},{"name":"Micro-biopsie guidée","price":25000,"free":false}]'::jsonb, 76,
   'Au CHU de Bogodogo, les deux appareils fonctionnent mais nous avons une forte affluence ce matin. Privilégiez le début d''après-midi.',
   'At Bogodogo University Hospital, both machines are operational but there is heavy attendance this morning. Early afternoon is recommended.',
   'CHU Bogodogo tʋmdame, la neb wʋsg n be kãenkãenga rũnda. Bɩ y bãng tɩ zãama nooma, sã n yaa ne yãmb yaa sõma tɩ y wa zaabre.',
   'CHU Bogodogo masinw bɛ baara kɛ, nka mɔgɔw ka ca bi. Ni aw bɛ fɛ, aw bɛ se ka na wula fɛ.',
   false),
  ('CHU Sourô Sanou (CHUSS) — Service Gynécologie', 'CHU Sourô Sanou', 'Centre-Ville, Bobo-Dioulasso', 'Bobo-Dioulasso', 'Avenue de la République, Bobo-Dioulasso', '+226 20 97 00 44', 11.178, -4.295, 'available'::public.statut_centre, 'Disponible · Équipe complète', 'Mammographe et échographe opérationnels', true, 5, '2 gynécologues, 3 sages-femmes dédiées', 12, '~25 min',
   '[{"name":"Auto-palpation guidée & Examen clinique","price":0,"free":true},{"name":"Échographie mammaire","price":7000,"free":false},{"name":"Mammographie numérique","price":12000,"free":false}]'::jsonb, 52,
   'Bonjour aux femmes de Bobo. Le service de dépistage est ouvert en continu jusqu''à 16 heures. L''équipe est au complet et prête à vous orienter.',
   'Hello to all women in Bobo-Dioulasso. Our screening unit is open continuously until 4 PM with complete medical staff.',
   'Bobo CHU Sourô Sanou pʋgẽ, b sɩngame tɩ b gũusd pagbã ne laafi. Ned baa a yembre pa be n gũud wʋsg ye. Wa-y tɩ b ges yãmba.',
   'I ni sɔgɔma Bobo musow. CHU Sourô Sanou dayɛlɛn bɛ fo ka taga se lere naani wula fɛ. Dɔgɔtɔrɔmusow bɛ yan k''aw bisimila.',
   false),
  ('Centre Hospitalier Régional (CHR) de Koudougou', 'CHR Koudougou', 'Secteur 1, Koudougou', 'Koudougou', 'Route de Ouagadougou, Secteur 1, Koudougou', '+226 25 44 01 24', 12.251, -2.366, 'maintenance'::public.statut_centre, 'Appareil en maintenance technique', 'Mammographe en révision (pièce attendue ce soir)', false, 2, '2 sages-femmes assurant les examens cliniques manuels', 3, '~10 min (Clinique uniquement)',
   '[{"name":"Palpation clinique manuelle","price":0,"free":true,"notes":"Maintenue normalement"},{"name":"Mammographie","price":10000,"free":false,"notes":"🔴 Suspendue aujourd''hui"}]'::jsonb, 19,
   'Attention pour le CHR de Koudougou : le mammographe est en maintenance. Les sages-femmes assurent la palpation manuelle gratuite.',
   'Notice for Koudougou Regional Hospital: mammography machine is under maintenance today. Manual clinical breast examinations remain open.',
   'CHR Koudougou: Masĩnã komsame bilfu tɩ b ket n manegda. La pagbã tõe n waame tɩ b ning-b nus n ges b yĩnsa zaalem.',
   'Koudougou CHR masin tiɲɛna dɔɔni bi. Musow bɛ se ka na dɔgɔtɔrɔmusow bɛ bɔlɔkɔrɔ lajɛ kɛ.',
   false),
  ('Centre Médical Urbain (CMU) Secteur 22', 'CMU Secteur 22', 'Tampouy, Ouagadougou', 'Ouagadougou', 'Tampouy, Arrondissement 3, Ouagadougou', '+226 25 35 12 00', 12.392, -1.554, 'outdated'::public.statut_centre, 'Non actualisé aujourd''hui', 'Statut non confirmé ce matin', false, 0, 'Rapport journalier non validé', 0, 'Inconnue',
   '[{"name":"Consultation d''orientation","price":1000,"free":false},{"name":"Palpation clinique","price":0,"free":true}]'::jsonb, 5,
   'Ce centre n''a pas encore validé son rapport ce matin. Veuillez appeler le centre avant de vous déplacer.',
   'This medical center has not confirmed daily status yet. Please call beforehand.',
   'Kasetã pa paam kʋdemd sebr rũnda ye. Bɩ y tẽeg n bãng bãmb sã n sɩngame tɩ y yaool n ta.',
   'Kɛnɛyaso nin ma kuma fɔ bi fɔlɔ. Aw k''u weele telefone fɛ k''a lɔn sani aw ka taga.',
   false)
) as v
where not exists (select 1 from public.centres);

insert into public.associations (nom, sigle, mission, ville, beneficiaires, verifiee)
select * from (values
  ('BE NEERE FOR CAUSE', 'BE NEERE', 'Organisation burkinabè pionnière : cliniques mobiles de dépistage gratuit, sensibilisation de proximité et prise en charge des femmes en milieu rural et périurbain.', 'Ouagadougou, Bobo & Centre-Nord', '2 800 femmes dépistées et accompagnées', false),
  ('WOMENTECHMAKERS & ORANGE DIGITAL CENTER', 'WTM / ODC', 'Synergie d''innovation numérique et sociale : développement de solutions e-santé locales, vulgarisation technologique contre le cancer et ateliers de sensibilisation pour les femmes.', 'Ouagadougou & Bobo-Dioulasso', '1 950 femmes formées et orientées', false),
  ('GENIT CARE BURKINA', 'GENIT CARE', 'Centre de référence en santé génésique de la femme : consultations gynécologiques bienveillantes, dépistage précoce, bilans sénologiques et prise en charge de l''endométriose.', 'Ouagadougou', '3 200 examens et bilans réalisés', false),
  ('Fonds de Solidarité Patientes — CMA de Schiphra', 'Fonds Schiphra', 'Subvention immédiate des mammographies, échographies et biopsies pour les patientes démunies adressées avec fiche d''orientation.', 'Ouagadougou (Tanghin)', '620 examens pris en charge', false),
  ('Association Burkinabè d''Action contre le Cancer', 'ABAC', 'Sensibilisation communautaire et plaidoyer pour l''accès universel aux traitements oncologiques au Burkina Faso.', 'Ouagadougou', '1 450 femmes touchées', false)
) as v
where not exists (select 1 from public.associations);

-- -----------------------------------------------------------------------------
-- Fiches de connaissance initiales de Rose IA (36 fiches = 9 thèmes × 4 langues)
-- Reprises de donnees/connaissancesRose.ts. Toutes EN ATTENTE de validation :
-- Rose IA ne les utilisera qu'après relecture, ajout d'une source officielle et
-- validation par un soignant validateur. « source_suggeree » n'est qu'une piste
-- à vérifier (aucun lien n'est fourni volontairement).
-- Idempotent : relancer le seed n'insère pas de doublon.
-- -----------------------------------------------------------------------------
insert into public.fiches_connaissance (titre, contenu, langue, groupe, theme, source_suggeree, cle_origine)
values
  ('J''ai senti une boule dans le sein', 'Respire calmement, ma sœur, ne panique pas : dans plus de 8 cas sur 10, une boule ou un nodule n''est PAS un cancer (il s''agit très souvent de simples kystes bénins d''eau ou d''adénofibromes fréquents). Cependant, la seule façon d''en avoir le cœur net et d''être en paix est de la faire examiner rapidement par une sage-femme ou un médecin. Je t''accompagne.', 'fr', 'boule', 'boule', 'SUGGESTION À VÉRIFIER — OMS, aide-mémoire « Cancer du sein » (site de l''OMS, rubrique Aide-mémoire).', 'seed:boule:fr'),
  ('I felt a lump in my breast', 'Breathe gently, my sister, do not panic: over 8 out of 10 breast lumps are NOT cancer (they are usually benign fluid cysts or fibroadenomas). However, having it examined promptly by a midwife or doctor brings complete peace of mind. I am with you.', 'en', 'boule', 'boule', 'SUGGESTION À VÉRIFIER — OMS, aide-mémoire « Cancer du sein » (site de l''OMS, rubrique Aide-mémoire).', 'seed:boule:en'),
  ('J''ai senti une boule dans le sein (Mooré)', 'Vʋʋsm sõma m maaso, da zoe rabeem ye: bõn-kʋds a nii (8) piig pʋgẽ pa bã-kãsenga ye (yaa kystes bal). La yaa tɩlae tɩ dɔgɔtɔr ges-a tao-tao tɩ fo sũur gãande. Mam be ne yãmba.', 'moore', 'boule', 'boule', 'SUGGESTION À VÉRIFIER — OMS, aide-mémoire « Cancer du sein » (site de l''OMS, rubrique Aide-mémoire).', 'seed:boule:moore'),
  ('J''ai senti une boule dans le sein (Dioula)', 'I ni lafiɲɛ dɔrɔn, kana siran : bõn-kʋdga tan kɔnɔ segin tɛ bana juguman ye. Nka kɛnɛyaso lajɛ jona de bɛ hakili sigi dɔgɔtɔrɔmuso fɛ. Ne b''i kɔrɔ.', 'dioula', 'boule', 'boule', 'SUGGESTION À VÉRIFIER — OMS, aide-mémoire « Cancer du sein » (site de l''OMS, rubrique Aide-mémoire).', 'seed:boule:dioula'),
  ('La mammographie fait-elle mal ?', 'Rassurez-vous avec tendresse : la mammographie ne fait généralement pas mal. C''est une pression ferme mais très brève (5 à 10 secondes par image) pour bien visualiser les tissus. Pour un confort optimal, prévoyez votre examen dans les 10 jours suivant la fin de vos règles, quand la poitrine est très souple.', 'fr', 'mal', 'mal', null, 'seed:mal:fr'),
  ('Does a mammogram hurt?', 'Rest assured with calm: mammography is generally not painful. It is a brief compression (5 to 10 seconds per view) to clearly display breast tissue. For greatest comfort, schedule it within 10 days after your period ends.', 'en', 'mal', 'mal', null, 'seed:mal:en'),
  ('La mammographie fait-elle mal ? (Mooré)', 'Da zoe rabeem ye: mammographie masĩnã pa namsd ninsaal wʋsg ye. A rɩkda sekõnd a wãn bal n kaset. Sã n mik tɩ y kẽngda pʋg-peelgã poore, yĩnsã tara pãng tɩ pa namsd ye.', 'moore', 'mal', 'mal', null, 'seed:mal:moore'),
  ('La mammographie fait-elle mal ? (Dioula)', 'I kana siran: masin nin tɛ mɔgɔ dimi kosɛbɛ. A bɛ kɛ sekondi damanin dɔrɔn lo kɔnɔ. Ni kalo-sira banna, o de ye wagati ɲuman ye ka taga lajɛ kɛ.', 'dioula', 'mal', 'mal', null, 'seed:mal:dioula'),
  ('Dépistage du cancer du col de l''utérus', 'Le col de l''utérus mérite toute ton attention : le cancer du col de l''utérus est l''un des plus fréquents en Afrique, mais c''est aussi le plus facile à éviter ! Un simple dépistage par inspection visuelle (test IVA) ou frottis, réalisé en quelques minutes par une sage-femme, permet de repérer et traiter d''éventuelles lésions bien avant qu''elles ne deviennent graves. C''est rapide, indolore et disponible dans les CSPS et CMA du Burkina. Fais ce dépistage tous les 3 ans !', 'fr', 'col_uterus', 'col_uterus', 'SUGGESTION À VÉRIFIER — OMS, « Lignes directrices pour le dépistage et le traitement des lésions précancéreuses du col de l''utérus » (2e édition, 2021). Attention : la fiche indique un dépistage « tous les 3 ans », à confronter aux recommandations en vigueur (l''intervalle dépend du test utilisé).', 'seed:col_uterus:fr'),
  ('Cervical cancer screening', 'Cervical health is vital: cervical cancer is common, yet completely preventable! A quick visual inspection (VIA test) or pap smear performed in minutes by a midwife detects precancerous lesions years in advance. It is fast, painless, and available at health centers across Burkina Faso. Get screened every 3 years!', 'en', 'col_uterus', 'col_uterus', 'SUGGESTION À VÉRIFIER — OMS, « Lignes directrices pour le dépistage et le traitement des lésions précancéreuses du col de l''utérus » (2e édition, 2021). Attention : la fiche indique un dépistage « tous les 3 ans », à confronter aux recommandations en vigueur (l''intervalle dépend du test utilisé).', 'seed:col_uterus:en'),
  ('Dépistage du cancer du col de l''utérus (Mooré)', 'Pʋg-kɛenga laafi yaa tɩlae wʋsg. Bãaga wã tõe n gɩdgame sã n mik tɩ dɔgɔtɔr ges-a zĩigẽ (test IVA). A pa namsd ye, a pa rɩkd wakat wʋsg ye, la a bee Burkina Faso kɛnɛyaso fãa pʋgẽ. Bãng-y fo laafi yʋʋm a tãab fãa pʋgẽ.', 'moore', 'col_uterus', 'col_uterus', 'SUGGESTION À VÉRIFIER — OMS, « Lignes directrices pour le dépistage et le traitement des lésions précancéreuses du col de l''utérus » (2e édition, 2021). Attention : la fiche indique un dépistage « tous les 3 ans », à confronter aux recommandations en vigueur (l''intervalle dépend du test utilisé).', 'seed:col_uterus:moore'),
  ('Dépistage du cancer du col de l''utérus (Dioula)', 'Kɔnɔna juru bana bɛ se ka bali sani a ka juguya. Dɔgɔtɔrɔmuso bɛ se k''a lajɛ sekondi damanin kɔnɔ (test IVA). A tɛ dimi, a tɛ mɔgɔ namsi, a bɛ sɔrɔ an ka kɛnɛyasow bɛɛ la. O kɛ kalo 36 o kalo 36 kɔnɔ.', 'dioula', 'col_uterus', 'col_uterus', 'SUGGESTION À VÉRIFIER — OMS, « Lignes directrices pour le dépistage et le traitement des lésions précancéreuses du col de l''utérus » (2e édition, 2021). Attention : la fiche indique un dépistage « tous les 3 ans », à confronter aux recommandations en vigueur (l''intervalle dépend du test utilisé).', 'seed:col_uterus:dioula'),
  ('Soulager les douleurs de règles', 'Je te comprends tellement, les douleurs de règles peuvent être très éprouvantes. Voici des gestes doux et naturels pour t''apaiser : applique un linge ou une bouillotte tiède sur ton bas-ventre, bois une infusion chaude de gingembre ou de kinkeliba, masse doucement ton ventre avec un peu de beurre de karité, et repose-toi. Prends du paracétamol si nécessaire, mais si les douleurs sont si intenses qu''elles t''empêchent de te lever ou de travailler, cela peut être le signe d''une affection comme l''endométriose : parle-en à un gynécologue.', 'fr', 'regles_douleurs', 'regles_douleurs', 'SUGGESTION À VÉRIFIER — OMS, aide-mémoire « Endométriose ».', 'seed:regles_douleurs:fr'),
  ('Relieving period pain', 'I hear you, menstrual pain can be genuinely debilitating. To soothe cramps naturally: apply a warm cloth to your lower belly, drink warm ginger or kinkeliba tea, gently massage with shea butter, and take rest. If cramps are severe and prevent your normal activities, consult a gynecologist to check for conditions like endometriosis.', 'en', 'regles_douleurs', 'regles_douleurs', 'SUGGESTION À VÉRIFIER — OMS, aide-mémoire « Endométriose ».', 'seed:regles_douleurs:en'),
  ('Soulager les douleurs de règles (Mooré)', 'Pʋg-tõor namsda pagb wʋsg. Bõn-sõma n tõe n koms-a: ning-y fu-tʋʋlga y pʋgẽ, nyũ-y gingembre koom bɩ kinkeliba ko-tʋʋlga, rɩk karité kam n so y pʋgã bilfu, la y vʋʋse. Sã n mik tɩ pʋg-tõorã yɩɩ kãsenga wʋsg hal n pa tõe n yĩk, kẽng n ges dɔgɔtɔrã.', 'moore', 'regles_douleurs', 'regles_douleurs', 'SUGGESTION À VÉRIFIER — OMS, aide-mémoire « Endométriose ».', 'seed:regles_douleurs:moore'),
  ('Soulager les douleurs de règles (Dioula)', 'Kalo-sira dimi bɛ muso caman tɔɔrɔ. Walasa k''a dɔgɔya: fɛn kaliman bila i kɔnɔ la, jinɛbɛrɛ-ji sumana min, si-tulu dɔoni kɛ i kɔnɔ la ka lafiɲɛ kɛ. Ni dimi ka bon kojugu fo i tɛ se ka wuli, taga dɔgɔtɔrɔ fɛ k''a sɛgɛsɛgɛ.', 'dioula', 'regles_douleurs', 'regles_douleurs', 'SUGGESTION À VÉRIFIER — OMS, aide-mémoire « Endométriose ».', 'seed:regles_douleurs:dioula'),
  ('Hygiène intime au quotidien', 'Ma sœur, ton intimité est précieuse et délicate. La règle d''or des soignants est simple : lave uniquement la partie extérieure (la vulve) à l''eau propre ou avec un savon doux sans parfum. Ne fais JAMAIS de douche vaginale interne ni n''introduis de poudres ou produits décapants : le vagin possède son propre système d''auto-nettoyage et ces produits détruisent ses défenses naturelles. Porte des sous-vêtements en coton pour laisser respirer ta peau avec la chaleur. Si tu as des démangeaisons, une sensation de brûlure ou des pertes odorantes, viens sans aucune honte consulter une sage-femme.', 'fr', 'hygiene_intime', 'hygiene_intime', null, 'seed:hygiene_intime:fr'),
  ('Everyday intimate hygiene', 'My sister, your intimate health is precious. Wash only the external area (the vulva) with clean water or mild unscented soap. NEVER practice internal vaginal douching or use harsh astringents: the vagina cleanses itself naturally. Wear breathable cotton underwear. If you experience itching, burning, or unusual discharge, visit a midwife with confidence and no shame.', 'en', 'hygiene_intime', 'hygiene_intime', null, 'seed:hygiene_intime:en'),
  ('Hygiène intime au quotidien (Mooré)', 'M maaso, fo yĩng sõngr yaa tɩlae wʋsg. Rɩk koom sõma bal n peeg fo meng yĩng zĩ-kẽemã yell bal. Da rɩk tɩɩm dãmb n kẽes fo pʋgẽ ye, bala a sãamda fo yĩnsa laafi. Yeelg fu-kõbdo sẽn yaa koton. Sã n mik tɩ yĩn-wẽk bee fo laafɩ wɛɛngẽ, kẽng n ges dɔgɔtɔr-pʋgbo.', 'moore', 'hygiene_intime', 'hygiene_intime', null, 'seed:hygiene_intime:moore'),
  ('Hygiène intime au quotidien (Dioula)', 'N ma muso, i yɛrɛ saniya ko ka kɔrɔtanin kosɛbɛ. Ji saniya dɔrɔn de kɛ kɔkan, kana fɛn juguw don kɔnɔna na abada. Saniya fɛnw bɛ kɛnɛya tiɲɛ. Koton faniw don funteni senfɛ. Ni fɛn dɔ y''i gɛlɛya walima ka dimi, taga dɔgɔtɔrɔmuso fɛ sabali.', 'dioula', 'hygiene_intime', 'hygiene_intime', null, 'seed:hygiene_intime:dioula'),
  ('Alimentation locale et vitalité', 'Pour préserver ta vitalité et ta santé au Burkina Faso, la nature nous a offert des trésors extraordinaires : les feuilles de Moringa (véritable ''arbre de vie'') regorgent de fer contre la fatigue et l''anémie, la pulpe de Baobab (pain de singe) est un concentré de vitamine C et d''antioxydants, et le Soumbala traditionnel protège le cœur et la tension. Évite les bouillons cubes industriels trop salés qui fatiguent les reins, et bois au moins 2 à 3 litres d''eau propre par jour pour compenser la chaleur sahélienne.', 'fr', 'nutrition_locale', 'nutrition_locale', 'SUGGESTION À VÉRIFIER — OMS, aide-mémoire « Alimentation saine » (pour les principes généraux uniquement ; les affirmations sur le moringa, le baobab et le soumbala restent à sourcer).', 'seed:nutrition_locale:fr'),
  ('Local foods and vitality', 'To boost your vitality in our Sahelian climate, local foods are true superfoods: Moringa leaves provide abundant iron against anemia, Baobab fruit (pain de singe) is rich in vitamin C and antioxidants, and authentic Soumbala supports heart health. Reduce salty industrial seasoning cubes, and drink 2 to 3 liters of clean water daily to stay well hydrated.', 'en', 'nutrition_locale', 'nutrition_locale', 'SUGGESTION À VÉRIFIER — OMS, aide-mémoire « Alimentation saine » (pour les principes généraux uniquement ; les affirmations sur le moringa, le baobab et le soumbala restent à sourcer).', 'seed:nutrition_locale:en'),
  ('Alimentation locale et vitalité (Mooré)', 'Burkina Faso ka, Wẽnd kõ-d-la rɩɩb sõma wʋsg: moringa vaadã kẽesda pãng fo zɩlem pʋgẽ n gɩdg zɩ-komlem, tɔɔd bɩ zɩt-yɩla waoogda pãng, la sumbala sõngda sũurã laafi. Gɩdg yĩn-kũud tɩɩm dãmb sẽn tar yaalem wʋsg, la nyũ-y ko-sõma litr a yiibu n ta a tãabo dahar fãa.', 'moore', 'nutrition_locale', 'nutrition_locale', 'SUGGESTION À VÉRIFIER — OMS, aide-mémoire « Alimentation saine » (pour les principes généraux uniquement ; les affirmations sur le moringa, le baobab et le soumbala restent à sourcer).', 'seed:nutrition_locale:moore'),
  ('Alimentation locale et vitalité (Dioula)', 'An ka faso la, kɛnɛya dumunifɛnw caman bɛ yen: moringa buluw bɛ fanga di joliko la, sira-den bɛ kɛnɛya gansan di, ani sumbala bɛ dusu mara. Maggi cube ka caya tɛ kɛnɛya ye, ji min litiri fila fo saba don o don funteni senfɛ.', 'dioula', 'nutrition_locale', 'nutrition_locale', 'SUGGESTION À VÉRIFIER — OMS, aide-mémoire « Alimentation saine » (pour les principes généraux uniquement ; les affirmations sur le moringa, le baobab et le soumbala restent à sourcer).', 'seed:nutrition_locale:dioula'),
  ('Bien-être mental et charge mentale', 'Ma sœur, pose ce fardeau quelques instants et écoute ton cœur : tu passes tes journées à prendre soin des autres, de la famille et du foyer, mais qui prend soin de toi ? Ton esprit et ton corps ont besoin de douceur. Respire profondément trois fois en fermant les yeux. Tu as le droit d''être fatiguée, tu as le droit de dire non, tu as le droit de te reposer. Tu n''es pas seule, je suis là pour veiller sur toi avec toute ma tendresse.', 'fr', 'bien_etre_mental', 'bien_etre_mental', 'SUGGESTION À VÉRIFIER — OMS, aide-mémoire « Santé mentale : renforcer notre action ».', 'seed:bien_etre_mental:fr'),
  ('Mental well-being and mental load', 'My sister, set down your burden for a moment: you spend your days caring for everyone else, but who cares for you? Your mind and body deserve gentle kindness. Take three deep breaths. You have the right to feel tired, to say no, and to rest. You are never alone; I am here with warmth and care.', 'en', 'bien_etre_mental', 'bien_etre_mental', 'SUGGESTION À VÉRIFIER — OMS, aide-mémoire « Santé mentale : renforcer notre action ».', 'seed:bien_etre_mental:en'),
  ('Bien-être mental et charge mentale (Mooré)', 'M maaso, vʋʋsm bilfu n kẽes sũ-noogo fo meng pʋgẽ. Fo tʋmda dahar fãa zakã neb yĩnga, la fo segd n ges fo meng me laafi. Vʋʋsm zĩ-sõngo. Fo tara sor n na n vʋʋse. Fo ka fo yembr ye, mam be ne fo dahar fãa.', 'moore', 'bien_etre_mental', 'bien_etre_mental', 'SUGGESTION À VÉRIFIER — OMS, aide-mémoire « Santé mentale : renforcer notre action ».', 'seed:bien_etre_mental:moore'),
  ('Bien-être mental et charge mentale (Dioula)', 'N ma muso, i lafiɲɛ dɔrɔn kɛ. I bɛ mɔgɔw bɛɛ ladon don o don, nka i yɛrɛ do? I ni lafiɲɛ fana kɔrɔtanin lo. Ni hakili-gɛlɛya b''i la, hakili saba minɛ. I ma kelen ye, an bɛ i kɔrɔ kosɛbɛ.', 'dioula', 'bien_etre_mental', 'bien_etre_mental', 'SUGGESTION À VÉRIFIER — OMS, aide-mémoire « Santé mentale : renforcer notre action ».', 'seed:bien_etre_mental:dioula'),
  ('Grossesse et ménopause : repères', 'Chaque étape de ta vie de femme est un voyage sacré. Que tu sois en désir d''enfant, enceinte, jeune maman ou en période de ménopause, ton corps s''adapte en permanence. Pendant la ménopause, les bouffées de chaleur et sautes d''humeur sont courantes : bois frais, consomme du soja et du calcium, et pratique la marche. Si tu as des saignements inattendus après la ménopause ou pendant la grossesse, consulte immédiatement un soignant.', 'fr', 'grossesse_menopause', 'grossesse_menopause', 'SUGGESTION À VÉRIFIER — OMS, aide-mémoire « Ménopause ».', 'seed:grossesse_menopause:fr'),
  ('Pregnancy and menopause: key points', 'Every stage of a woman''s journey is unique. Whether during pregnancy, postpartum, or menopause, your body evolves. During menopause, hot flashes and mood shifts are normal: stay hydrated, eat calcium-rich local foods, and take brisk walks. Any unexpected bleeding after menopause or during pregnancy requires prompt medical evaluation.', 'en', 'grossesse_menopause', 'grossesse_menopause', 'SUGGESTION À VÉRIFIER — OMS, aide-mémoire « Ménopause ».', 'seed:grossesse_menopause:en'),
  ('Grossesse et ménopause : repères (Mooré)', 'Pʋg-yãmb laafi tekda wakat fãa: pʋg-tũub wakat, bi-doglem wakat, bɩ kʋdemd wakat. Kʋdemdã sasa, tʋʋlg namsda pagb wʋsg. Nyũ-y ko-sumdo, rɩ-y rɩ-sõma. Sã n mik tɩ zɩɩm yii fo meng pʋgẽ tɩ pa wakat, kẽng dɔgɔtɔr tao-tao.', 'moore', 'grossesse_menopause', 'grossesse_menopause', 'SUGGESTION À VÉRIFIER — OMS, aide-mémoire « Ménopause ».', 'seed:grossesse_menopause:moore'),
  ('Grossesse et ménopause : repères (Dioula)', 'Musoya ye yɛlɛmali yɔrɔ ye: kɔnɔtigi, denbaya, walima musokɔrɔya. Musokɔrɔya sɔrɔlen, funteni kɔnɔna na bɛ se ka kɛ. Ji sumana min, dumuni kɛnɛ kɛ. Ni jolidon kɛra kɔfɛ, taga dɔgɔtɔrɔmuso fɛ jona.', 'dioula', 'grossesse_menopause', 'grossesse_menopause', 'SUGGESTION À VÉRIFIER — OMS, aide-mémoire « Ménopause ».', 'seed:grossesse_menopause:dioula'),
  ('Coûts du dépistage au Burkina Faso', 'Au Burkina Faso, la palpation clinique de dépistage est GRATUITE (0 FCFA) dans les centres publics et les campagnes associatives. L''échographie coûte entre 6 000 et 7 500 FCFA, et la mammographie environ 10 000 à 12 000 FCFA (subventionnée à 5 000 FCFA à Schiphra pour les femmes vulnérables). L''argent ne doit jamais être un frein à ta santé.', 'fr', 'prix', 'prix', null, 'seed:prix:fr'),
  ('Screening costs in Burkina Faso', 'In Burkina Faso, clinical breast exams are FREE (0 FCFA) at public centers and outreach campaigns. Ultrasound costs 6,000 to 7,500 FCFA, and mammography 10,000 to 12,000 FCFA (subsidized to 5,000 FCFA at Schiphra for vulnerable women). Financial worries should never keep you from care.', 'en', 'prix', 'prix', null, 'seed:prix:en'),
  ('Coûts du dépistage au Burkina Faso (Mooré)', 'Burkina Faso ka, nus n gesã yaa zaalem (0 FCFA) kɛnɛyaso wʋsg pʋgẽ. Échographie yaa 6 000 n ta 7 500 FCFA, la mammographie yaa 10 000 n ta 12 000 FCFA (subventionné a 5 000 FCFA Schiphra). Ligdi da yɩ gɩdgr fo laafɩ wɛɛngẽ ye.', 'moore', 'prix', 'prix', null, 'seed:prix:moore'),
  ('Coûts du dépistage au Burkina Faso (Dioula)', 'Burkina Faso la, bɔlɔkɔrɔ lajɛ sɔngɔ ye fu ye (0 FCFA). Échographie ye 6 000 fo 7 500 FCFA ye, mammographie ye 10 000 fo 12 000 FCFA ye. Wari kana kɛ gɛlɛya ye i ka kɛnɛya siratigɛ la.', 'dioula', 'prix', 'prix', null, 'seed:prix:dioula')
on conflict (cle_origine) do nothing;
